// Generated by `npx @musikhood-dev/auth-client init` — this file is yours, edit freely.
import { createAuthClient, isAuthErrorNamed } from '@musikhood-dev/auth-client'
import { toast } from '@@toast-module'

export const authClient = createAuthClient({
  baseUrl: import.meta.env.VITE_API_BASE_URL,
  loginPath: '/login',
  homePath: '/',
  broadcastSession: true,
})

// Shown inline by the login form / 2FA dialogs — no global report. `verifyMfa` and
// `stepUpMfa` also emit `login-error`; an expired session ends with a redirect to /login.
const INLINE_ERRORS = [
  'InvalidCredentialsError',
  'MfaRequiredError',
  'MfaEnrollmentRequiredError',
  'MfaInvalidCodeError',
  'MfaTokenExpiredError',
  'TooManyAttemptsError',
  'SessionExpiredError',
  'DeviceMismatchError',
] as const

// ============================================================================
// TOAST: unexpected auth errors (403 without panel access, 5xx, network) go to the
// app's shadcn toast (detected: @@toast-module). Change freely.
// ============================================================================
export function reportAuthError(error: unknown, fallback: string): void {
  toast({
    title: fallback,
    description: error instanceof Error && error.message ? error.message : undefined,
    variant: 'destructive',
  })
}

authClient.on('login-error', (error) => {
  if (INLINE_ERRORS.some((name) => isAuthErrorNamed(error, name))) return
  reportAuthError(error, 'Nie udało się zalogować.')
})
